describe('No Results Found Message', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display "No results found" message when API returns empty list', () => {
    // Intercept the API call to return an empty list
    cy.intercept('GET', '/api/search?q=nonexistent').as('emptySearch');

    // Trigger the search API call
    cy.get('[data-testid="search-input"]').type('nonexistent');
    cy.wait('@emptySearch');

    // Verify the "No results found" message is displayed
    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .should('contain', 'No results found');

    // Verify the search input still exists and is not empty
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').should('have.value', 'nonexistent');

    // Verify the search button is still enabled
    cy.get('[data-testid="search-button"]').should('be.enabled');
  });

  it('should handle empty list gracefully without crashing', () => {
    // Intercept the API call to return an empty list
    cy.intercept('GET', '/api/search?q=empty').as('emptySearch');

    // Trigger the search API call
    cy.get('[data-testid="search-input"]').type('empty');
    cy.wait('@emptySearch');

    // Verify the page does not crash and remains responsive
    cy.get('[data-testid="page-title"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('be.visible');

    // Verify other page elements are still accessible
    cy.get('[data-testid="nav-menu"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('be.visible');

    // Verify the search button is still present and functional
    cy.get('[data-testid="search-button"]').should('be.visible');
    cy.get('[data-testid="search-button"]').click();

    // Verify the page reloads or navigates to a different state
    cy.url().should('include', '/search');
  });
});
